//! Native public constants and finite data tables.
//!
//! Generated by the external qualification constant-metadata generator.
//! Calculation constants reference their owning native kernels. Integer selectors
//! are dimensionless; physical units are documented by those kernels. These
//! immutable values perform no calculation and have no failure domain.

/// A public scalar or finite table in its native Rust representation.
#[derive(Clone, Copy, Debug)]
pub enum PublicConstantValue {
    /// Dimensionless body id, flag, model selector or output slot.
    Integer(i64),
    /// Binary64 physical constant; its owning kernel specifies its units.
    Float(f64),
    /// Asset name, public version or configuration key.
    Text(&'static str),
    /// An unordered finite set of integer body selectors.
    IntegerSet(&'static [i32]),
    /// Integer-keyed integer metadata.
    IntegerMap(&'static [(i32, i32)]),
    /// Integer-keyed names or explanatory text.
    IntegerTextMap(&'static [(i32, &'static str)]),
    /// Integer-keyed dimensionless scale factors.
    IntegerFloatMap(&'static [(i32, f64)]),
    /// Body id, Horizons designation and NAIF id.
    SpkIdentityMap(&'static [(i32, &'static str, i32)]),
    /// Body id, asteroid number, Horizons designation, NAIF id and name.
    MajorAsteroidMap(&'static [(i32, i32, &'static str, i32, &'static str)]),
}

